import { ref, onMounted } from "vue";
import { useAuthStore } from "../stores/useAuthStore";
import { useMatchStore } from "../stores/useMatchStore";
import { ArrowLeft, Plus, Radio, Trash2, X } from "lucide-vue-next";
const authStore = useAuthStore();
const matchStore = useMatchStore();
const matches = ref([]);
const loading = ref(false);
const showCreateModal = ref(false);
const newTourney = ref("MPL INDONESIA S14");
const newRound = ref("REGULAR SEASON");
const newFormat = ref("BO3");
const setAsActiveNow = ref(true);
async function fetchMatches() {
    loading.value = true;
    try {
        const res = await fetch("/api/matches");
        if (res.ok) {
            const data = await res.json();
            matches.value = data.matches || [];
        }
    }
    catch (err) {
        console.error("Gagal memuat matches:", err);
    }
    finally {
        loading.value = false;
    }
}
async function activateMatch(id) {
    try {
        const res = await fetch(`/api/matches/${id}/active`, {
            method: "POST",
            headers: { Authorization: `Bearer ${authStore.token}` },
        });
        if (res.ok) {
            await fetchMatches();
        }
    }
    catch (err) {
        console.error(err);
    }
}
async function handleCreateMatch() {
    try {
        const res = await fetch("/api/matches", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${authStore.token}`,
            },
            body: JSON.stringify({
                tournamentName: newTourney.value,
                roundName: newRound.value,
                format: newFormat.value,
                setAsActive: setAsActiveNow.value,
            }),
        });
        if (res.ok) {
            showCreateModal.value = false;
            await fetchMatches();
        }
    }
    catch (err) {
        console.error(err);
    }
}
async function deleteMatch(id) {
    if (!confirm("Hapus pertandingan ini dari database?"))
        return;
    try {
        const res = await fetch(`/api/matches/${id}`, {
            method: "DELETE",
            headers: { Authorization: `Bearer ${authStore.token}` },
        });
        if (res.ok) {
            matches.value = matches.value.filter((m) => m.id !== id);
        }
    }
    catch (err) {
        console.error(err);
    }
}
onMounted(() => {
    fetchMatches();
});
